<script>
async function refresh(){try{const r=await fetch('api.php?action=results&t='+Date.now(),{cache:'no-store'});const d=await r.json();if(!d.ok)throw Error('API error');document.getElementById('s1').textContent=d.scores[1];document.getElementById('s2').textContent=d.scores[2];document.getElementById('status').textContent='Connected · '+d.answers.length+' answers received';const names={chem:'රසායනික විද්‍යාව',physics:'භෞතික විද්‍යාව',bio:'ජීව විද්‍යාව',math:'සංයුක්ත ගණිතය',final:'Final'};document.getElementById('rows').innerHTML=d.answers.map(a=>`<tr><td>TEAM ${a.team}</td><td>${a.round}</td><td>${names[a.section]||a.section}</td><td>${Number(a.question)+1}</td><td>${String.fromCharCode(65+Number(a.answer))}</td><td class="${a.correct==1?'good':'bad'}">${a.correct==1?'✓ Correct':'✗ Wrong'}</td><td>${a.updated_at}</td></tr>`).join('')||'<tr><td colspan="7">තවම පිළිතුරු ලැබී නැත</td></tr>';}catch(e){document.getElementById('status').textContent='Server connection error · '+e.message}}
refresh();setInterval(refresh,1000);
</script></body></html>
